  requireRecord(record);
  return Object.keys(record).map(name => ({ name, accepts: compileRange(record[name]) }));
}

function candidateOrder(left, right) {
  const a = left.tuple.join('.');
  const b = right.tuple.join('.');
  return a === b ? 0 : a < b ? 1 : -1;
